def X(name, eq="", pat="", p="", s="", next="", how=None, metrics="RW", video=""):
    """One exercise. eq/pat/p(rimary)/s(econdary)/next are comma-separated names; metrics are letters:
    R Reps, W Weight, D Duration, C Calories, X Resistance, M Distance. `how` (instructions) is only
    given for new exercises; existing ones keep their own instructions, metrics and video."""
    split = lambda text: [part.strip() for part in text.split(",") if part.strip()]
    return {"name": name, "equipment": split(eq), "patterns": split(pat), "primary": split(p), "secondary": split(s),
            "next": split(next), "instructions": how, "metrics": metrics, "video_url": video}


